stage.plugins/agentpack-bundle/hooks/hooks.jso:
{
  "hooks": {
    "PreToolUse": [
      {
        "hooks": [
          {
            "command": "agentpack hook-exec command --target claude --spec $ROOT/hooks/_packages/fixture/specs/000-000-000.json",
            "type": "command"
          }
        ],
        "matcher": "Bash"
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "command": "agentpack hook-exec inject-guidance --target claude --event SessionStart --file $ROOT/_agentpack/guidance.md",
            "type": "command"
          }
        ]
      }
    ]
  }
}
